import json
d=json.load(open('/tmp/claude-0/npmaudit.json'))
v=d['vulnerabilities']

def collect(name, seen=None, advisories=None):
    if seen is None: seen=set()
    if advisories is None: advisories=set()
    if name in seen: return advisories
    seen.add(name)
    if name not in v: return advisories
    e = v[name]
    for item in e['via']:
        if isinstance(item, str):
            collect(item, seen, advisories)
        else:
            advisories.add(item.get('url'))
    return advisories

direct = ['express','body-parser','mongodb','underscore','swig','marked','helmet','csurf','express-session','forever','async','grunt','mocha','nodemon','selenium-webdriver','cypress','zaproxy','jshint','grunt-cli','grunt-contrib-jshint','grunt-contrib-watch','grunt-if','grunt-npm-install','grunt-retire']
for n in direct:
    advs = collect(n)
    own = [it for it in v[n]['via'] if not isinstance(it,str)]
    print(n, '-> total unique advisories in tree:', len(advs), '| direct-on-package:', len(own), '| transitive-only:', len(advs)-len(own))
"
","description":"Count transitive advisories per direct dependency"}

